<!doctype html><html><head><style>body{font-family:DejaVu Sans;font-size:12px;color:#222}.head{border-bottom:2px solid #222;padding-bottom:12px}.right{float:right;text-align:right}.clear{clear:both}table{width:100%;border-collapse:collapse;margin-top:24px}th,td{border:1px solid #555;padding:8px;text-align:left}th{background:#eee}.num{text-align:right}.footer{margin-top:40px;font-size:10px}</style></head><body><div class="head"><div class="right"><b>SALES INVOICE</b><br>Invoice: {{ $invoice->invoice_number }}<br>Date: {{ $invoice->invoice_date->format('d-m-Y') }}</div><h1>{{ $profile?->name ?? 'Indus Gas' }}</h1><div>{{ $profile?->address }}<br>{{ $profile?->phone }} @if($profile?->ntn) · NTN: {{ $profile->ntn }}@endif</div><div class="clear"></div></div><h3>Bill To</h3><b>{{ $invoice->customer->title }}</b><br>{{ $invoice->customer->billing_address ?: $invoice->customer->location }}<br>{{ $invoice->customer->phone }} @if($invoice->customer->ntn) · NTN: {{ $invoice->customer->ntn }}@endif<table><thead><tr><th>Description</th><th class="num">Qty</th><th class="num">KG</th><th class="num">Rate / KG</th><th class="num">Amount</th></tr></thead><tbody>@foreach($invoice->delivery->items as $item)<tr><td>{{ $item->cylinderType->name }}</td><td class="num">{{ $item->delivered_quantity }}</td><td class="num">{{ number_format($item->delivered_quantity*$item->cylinderType->capacity_kg,2) }}</td><td class="num">{{ number_format($invoice->rate_per_kg,2) }}</td><td class="num">{{ number_format($item->delivered_quantity*$item->cylinderType->capacity_kg*$invoice->rate_per_kg,2) }}</td></tr>@endforeach<tr><th colspan="2">Total</th><th class="num">{{number_format($invoice->total_kg,2)}}</th><th></th><th class="num">Rs. {{number_format($invoice->total_amount,2)}}</th></tr></tbody></table><p class="footer">{{ $profile?->invoice_footer }}<br><br>Prepared By ____________________ &nbsp;&nbsp;&nbsp; Received By ____________________</p></body></html>
